mutants_xǁSizeRejectedǁ__init____mutmut['_mutmut_orig'] = SizeRejected.xǁSizeRejectedǁ__init____mutmut_orig # type: ignore # mutmut generated
mutants_xǁSizeRejectedǁ__init____mutmut['xǁSizeRejectedǁ__init____mutmut_1'] = SizeRejected.xǁSizeRejectedǁ__init____mutmut_1 # type: ignore # mutmut generated
