@dataclass(frozen=True)
class SizePlan:
    notional_usdt: float
    qty: float
    reserved_risk: float
    stop_pct: float
    stressed_cost_pct: float
    adverse_price: float
mutants_x__finite__mutmut: MutantDict = {}  # type: ignore


@_mutmut_mutated(mutants_x__finite__mutmut)
def _finite(value: float) -> bool:
    return isinstance(value, (int, float)) and math.isfinite(value)


def x__finite__mutmut_orig(value: float) -> bool:
    return isinstance(value, (int, float)) and math.isfinite(value)


def x__finite__mutmut_1(value: float) -> bool:
    return isinstance(value, (int, float)) or math.isfinite(value)


def x__finite__mutmut_2(value: float) -> bool:
    return isinstance(value, (int, float)) and math.isfinite(None)

mutants_x__finite__mutmut['_mutmut_orig'] = x__finite__mutmut_orig # type: ignore # mutmut generated
mutants_x__finite__mutmut['x__finite__mutmut_1'] = x__finite__mutmut_1 # type: ignore # mutmut generated
