        # skips (never sizes into a breached budget).
        if not _finite(risk_budget_cap_usdt):
            raise SizeRejected("health:nonfinite-account")
        if risk_budget_cap_usdt <= 0:
            raise SizeRejected("skip:remaining-budget")
