    if not _finite(fee_buffer_usdt) or fee_buffer_usdt < 0:
        raise SizeRejected("health:nonfinite-account")
    if not _finite(inflight_exposure_usdt) or inflight_exposure_usdt < 0:
        raise SizeRejected("health:nonfinite-account")
